import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync,statfsSync} from 'node:fs';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
const root=process.env.CAD_REPO,dir=process.env.CAD_RECOVERY_DIR;
assert.ok(root&&dir&&process.execArgv.includes('--no-opt'));mkdirSync(dir,{recursive:true});
const {cad}=await import(pathToFileURL(resolve(dir,'cad-source.mjs')));
const {prepareAxisBoxBooleanBuffers}=await import(pathToFileURL(resolve(dir,'gpu-source.mjs')));
const {recessedPlate,provePlate,proveBuffers,nativeBodyHash}=await import(pathToFileURL(resolve(root,'packages/barocss-cad/test/modeling-box-cut-fixture.mjs')));
const hash=x=>createHash('sha256').update(x).digest('hex');
const flow={status:'running',scope:'NEW replacement fixtures after lost unpublished #1653 candidate; historical PASS is not reused',base:'ee461c114d34c02fae513b2adff84313e3466109',runtime:process.version,modelCalls:0,cpuPreparations:0,stages:[],UV:'helper omits sampled UV arrays; original native pcurve coefficients retained for explicitly adapted replay'};
const write=()=>writeFileSync(resolve(dir,'native-recovery.json'),JSON.stringify(flow,null,2)+'\n');
function disk(){const s=statfsSync(dir);assert.ok(s.bavail*s.bsize>=524288000);}
function model(label,action){disk();assert.ok(++flow.modelCalls<=2);flow.pending=label;write();const start=performance.now(),s=action();flow.stages.push({label,milliseconds:performance.now()-start,recomputation:s.recomputation});flow.pending=null;write();return s;}
function transfer(name,s,buffers){const text=JSON.stringify({text:s.save(),parameters:s.parameters,features:s.features,bodies:s.bodies,bodySHA256:nativeBodyHash(s),...(buffers?{buffers:{...buffers,positions:Array.from(buffers.positions),normals:Array.from(buffers.normals),indices:Array.from(buffers.indices)}}:{})})+'\n';writeFileSync(resolve(dir,name),text);return{bytes:Buffer.byteLength(text),sha256:hash(text)};}
try {
 const initial=model('baseline depth4',recessedPlate(cad).build);flow.baseline=provePlate(initial,5632,46);assert.ok(Object.is(initial.bodies.part.native.a.shell.origin[0],-0));
 disk();assert.equal(++flow.cpuPreparations,1);flow.pending='one baseline CPU preparation';write();
 const buffers=prepareAxisBoxBooleanBuffers(initial.bodies.part.native,{basis:'authored-xyz-matches-rhyup',mmToSceneUnit:1,translate:[0,0,0]});flow.cpu=proveBuffers(initial.bodies.part.native,buffers);flow.pending=null;
 flow.baselineTransfer=transfer('baseline-native.json',initial,buffers);write();
 const window=model('same baseline depth8 window',()=>initial.withParameters({depth:8}));flow.window=provePlate(window,5120,32);flow.windowTransfer=transfer('window-native.json',window);assert.equal(flow.modelCalls,2);assert.equal(flow.cpuPreparations,1);
 flow.nativeBooleanRevalidations=1;flow.panelTessellations=46;flow.windowTessellations=0;flow.status='passed';write();
} catch(e){flow.status='failed';flow.failure={name:e.name,message:e.message,stack:e.stack};write();throw e;}
console.log(JSON.stringify({status:flow.status,modelCalls:flow.modelCalls,cpuPreparations:flow.cpuPreparations,baseline:flow.baselineTransfer,window:flow.windowTransfer}));

